from pathlib import Path
p=Path('frontend/app/player.tsx')
s=p.read_text()
# Add more state.
s=s.replace('  const [tracksOpen, setTracksOpen] = useState(false);', '  const [tracksOpen, setTracksOpen] = useState(false);\n  const [moreOpen, setMoreOpen] = useState(false);')
# Hide/reset all panels whenever controls auto-hide.
s=s.replace('      setControls(false);\n      setChannelsOpen(false);', '      setControls(false);\n      setChannelsOpen(false);\n      setTracksOpen(false);\n      setMoreOpen(false);', 1)
# Back handler: More before channels.
s=s.replace('      if (tracksOpen) {\n        setTracksOpen(false);\n        scheduleHide();\n        return true;\n      }\n      if (channelsOpen) {', '      if (tracksOpen) {\n        setTracksOpen(false);\n        scheduleHide();\n        return true;\n      }\n      if (moreOpen) {\n        setMoreOpen(false);\n        scheduleHide();\n        return true;\n      }\n      if (channelsOpen) {')
s=s.replace('  }, [channelsOpen, revealControls, scheduleHide, stopAndExit, tracksOpen]);', '  }, [channelsOpen, moreOpen, revealControls, scheduleHide, stopAndExit, tracksOpen]);')
# Make long down channels mutually exclusive.
s=s.replace('          setChannelsOpen(true);\n          scheduleHide();', '          setMoreOpen(false);\n          setTracksOpen(false);\n          setChannelsOpen(true);\n          scheduleHide();', 1)
# Replace controls row block between start and tracks panel.
start=s.index('            <View style={styles.controlsRow}>')
end=s.index('\n\n            {tracksOpen ? (', start)
new='''            <View style={styles.controlsRow}>\n              <Pressable onPress={goGuide} style={({ focused }: any) => [styles.textControl, focused && styles.focused]}>\n                <Ionicons name="information-circle-outline" size={15} color="#fff" />\n                <Text style={styles.controlLabel}>Guide</Text>\n              </Pressable>\n              <Pressable\n                ref={channelsButtonRef}\n                onPress={() => {\n                  setTracksOpen(false);\n                  setMoreOpen(false);\n                  setChannelsOpen((value) => !value);\n                  scheduleHide();\n                }}\n                style={({ focused }: any) => [styles.textControl, channelsOpen && styles.controlActive, focused && styles.focused]}\n              >\n                <Ionicons name="list" size={15} color="#fff" />\n                <Text style={styles.controlLabel}>Channels</Text>\n              </Pressable>\n              <View style={styles.controlsSpacer} />\n              <Pressable\n                ref={prevButtonRef}\n                disabled={streamChannels.length < 2}\n                onPress={() => stepChannel(-1)}\n                style={({ focused }: any) => [styles.iconControl, focused && styles.focused]}\n              >\n                <Ionicons name="play-skip-back" size={18} color="#fff" />\n              </Pressable>\n              <Pressable\n                accessibilityLabel={playbackPaused ? "Play stream" : "Pause stream"}\n                onPress={() => {\n                  setPlaybackPaused((value) => !value);\n                  revealControls({ claimChannelsFocus: false });\n                }}\n                style={({ focused }: any) => [styles.pauseControl, focused && styles.focused]}\n              >\n                <Ionicons name={playbackPaused ? "play" : "pause"} size={18} color="#fff" />\n              </Pressable>\n              <Pressable\n                ref={nextButtonRef}\n                disabled={streamChannels.length < 2}\n                onPress={() => stepChannel(1)}\n                style={({ focused }: any) => [styles.iconControl, focused && styles.focused]}\n              >\n                <Ionicons name="play-skip-forward" size={18} color="#fff" />\n              </Pressable>\n              <View style={styles.controlsSpacer} />\n              <Pressable\n                onPress={() => {\n                  setChannelsOpen(false);\n                  setTracksOpen(false);\n                  setMoreOpen((value) => !value);\n                  scheduleHide();\n                }}\n                style={({ focused }: any) => [styles.textControl, moreOpen && styles.controlActive, focused && styles.focused]}\n              >\n                <Ionicons name="ellipsis-horizontal" size={15} color="#fff" />\n                <Text style={styles.controlLabel}>More</Text>\n              </Pressable>\n              <Pressable onPress={stopAndExit} style={({ focused }: any) => [styles.textControl, focused && styles.focused]}>\n                <Ionicons name="stop" size={15} color="#fff" />\n                <Text style={styles.controlLabel}>Stop</Text>\n              </Pressable>\n            </View>\n\n            {moreOpen ? (\n              <View style={styles.tracksPanel}>\n                <Pressable\n                  onPress={() => { setMoreOpen(false); setTracksOpen(true); scheduleHide(); }}\n                  style={({ focused }: any) => [styles.trackRow, focused && styles.focused]}\n                >\n                  <Ionicons name="musical-notes-outline" size={15} color="#fff" />\n                  <Text style={styles.controlLabel}>Audio / Subtitles</Text>\n                </Pressable>\n                <Pressable onPress={cycleScaleMode} style={({ focused }: any) => [styles.trackRow, focused && styles.focused]}>\n                  <Ionicons name="resize-outline" size={15} color="#fff" />\n                  <Text style={styles.controlLabel}>Aspect · {scaleMode === "fit" ? "Fit" : scaleMode === "zoom" ? "Zoom" : "Stretch"}</Text>\n                </Pressable>\n                <Pressable\n                  onPress={() => {\n                    const next = sleepTimerMinutes === 0 ? 15 : sleepTimerMinutes === 15 ? 30 : sleepTimerMinutes === 30 ? 60 : sleepTimerMinutes === 60 ? 90 : 0;\n                    setSleepTimerMinutes(next);\n                    showNotice(next ? `Sleep timer: ${next} min` : "Sleep timer: Off");\n                    scheduleHide();\n                  }}\n                  style={({ focused }: any) => [styles.trackRow, focused && styles.focused]}\n                >\n                  <Ionicons name="moon-outline" size={15} color="#fff" />\n                  <Text style={styles.controlLabel}>Sleep Timer · {sleepTimerMinutes ? `${sleepTimerMinutes}m` : "Off"}</Text>\n                </Pressable>\n                <Pressable onPress={() => router.replace("/settings" as any)} style={({ focused }: any) => [styles.trackRow, focused && styles.focused]}>\n                  <Ionicons name="settings-outline" size={15} color="#fff" />\n                  <Text style={styles.controlLabel}>Settings</Text>\n                </Pressable>\n                <Pressable onPress={() => void saveAudioReport()} style={({ focused }: any) => [styles.trackRow, focused && styles.focused]} testID="player-report-audio">\n                  <Ionicons name="bug-outline" size={15} color="#fff" />\n                  <Text style={styles.controlLabel}>Diagnostics</Text>\n                </Pressable>\n              </View>\n            ) : null}'''
s=s[:start]+new+s[end:]
# Tracks button state should close other overlays and timer continues; once existing panel appears no duplication.
# Surface tap hide must reset all panel states.
s=s.replace('            setControls(false);\n            setChannelsOpen(false);', '            setControls(false);\n            setChannelsOpen(false);\n            setTracksOpen(false);\n            setMoreOpen(false);', 1)
p.write_text(s)

p=Path('frontend/scripts/verify-overhaul-architecture.mjs')
s=p.read_text()
marker='console.log("TiViMate architecture-overhaul conflict scan passed.");'
checks='''// OSD state/overflow architecture.\nrequireText("app/player.tsx", "setMoreOpen", "player overflow state is missing");\nrequireText("app/player.tsx", ">More<", "player More action is missing");\nrequireText("app/player.tsx", "Sleep Timer ·", "player sleep-timer quick action is missing");\nrequireText("app/player.tsx", "setTracksOpen(false);\\n      setMoreOpen(false);", "auto-hide does not release secondary OSD state");\n'''
if '// OSD state/overflow architecture.' not in s:
    s=s.replace(marker,checks+'\n'+marker)
# Correct prior brittle Stop assertion.
s=s.replace('requireText("app/player.tsx", ">Stop<", "explicit player Stop control is missing");', 'requireText("app/player.tsx", "<Text style={styles.controlLabel}>Stop</Text>", "explicit player Stop control is missing");')
p.write_text(s)
